// @ts-check

/** @type {Record<string, Http2ClientBrowser>} */
export const clients = {}

const MAX_ATTEMPTS = 2
const DEFAULT_CONNECT_TIMEOUT_SECONDS = 120
const DEFAULT_CONNECT_TIMEOUT_MS = DEFAULT_CONNECT_TIMEOUT_SECONDS * 1000
const DEFAULT_RESPONSE_TIMEOUT_SECONDS = 180
const DEFAULT_RESPONSE_TIMEOUT_MS = DEFAULT_RESPONSE_TIMEOUT_SECONDS * 1000

/**
 * @typedef {import('../../utils/connectionData/Http2ConnectionData.js').Http2ConnectionData} Http2ConnectionData
 */

class Http2ClientBrowser {
    /**
     * @param {Http2ConnectionData} connectionData
     * @param {{ isDisconnectedAfterMessage: boolean }} [options]
     */
    constructor(connectionData, options) {
        this.connectionData = connectionData
        this.url = connectionData.hostname
        const parsedUrl = new URL(this.url)
        if (parsedUrl.protocol !== 'https:') {
            throw new Error(
                `Browser HTTP/2 requests require an https URL. Browsers do not expose h2c for ${this.url}.`
            )
        }
        this.isDisconnectedAfterMessage = options?.isDisconnectedAfterMessage ?? false
        this.responseTimeoutInSeconds =
            connectionData.responseTimeoutInSeconds ?? DEFAULT_RESPONSE_TIMEOUT_SECONDS
        this.requestHeaders = this._buildRequestHeadersFromConnectionData()
    }

    get cacheKey() {
        return this.connectionData.toCanonicalKey()
    }

    /**
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    async send(messageArray) {
        if (messageArray == null) {
            throw new Error('messageArray must not be null or undefined')
        }

        clients[this.cacheKey] = this
        const body = await this._sendWithRetry(messageArray)

        if (this.isDisconnectedAfterMessage) {
            this.disconnect()
        }
        return body
    }

    disconnect() {
        delete clients[this.cacheKey]
    }

    /**
     * Browsers negotiate HTTP/2 internally when available; JavaScript cannot force it.
     * @private
     * @returns {Record<string, string>}
     */
    _buildRequestHeaders() {
        return this.requestHeaders
    }

    /**
     * @private
     * @returns {Record<string, string>}
     */
    _buildRequestHeadersFromConnectionData() {
        /** @type {Record<string, string>} */
        const requestHeaders = {
            'content-type': 'application/octet-stream',
        }
        for (const [key, value] of Object.entries(this.connectionData.getHeaders())) {
            requestHeaders[key] = value
        }
        return requestHeaders
    }

    /**
     * @private
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    async _sendWithRetry(messageArray) {
        let lastError = null

        for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            try {
                return await this._sendOnce(messageArray)
            } catch (error) {
                lastError = error
                if (!isTransientHttp2BrowserError(error)) {
                    // Evict desynced/broken connection after final failure (bug 32346).
                    this.disconnect()
                    throw error
                }
                if (attempt === MAX_ATTEMPTS - 1) {
                    break
                }
            }
        }

        // Evict desynced/broken connection after final failure (bug 32346).
        this.disconnect()
        throw new Error(
            `HTTP/2 send to ${this.url} failed after ${MAX_ATTEMPTS} attempts. Last error: ${getErrorMessage(lastError)}`
        )
    }

    /**
     * @private
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    async _sendOnce(messageArray) {
        const controller = new AbortController()
        let phase = 'connect'
        const connectTimeout = setTimeout(() => controller.abort(), DEFAULT_CONNECT_TIMEOUT_MS)

        const response = await fetch(this.url, {
            method: 'POST',
            headers: this._buildRequestHeaders(),
            body: /** @type {BodyInit} */ (messageArray),
            signal: controller.signal,
        })
            .catch((error) => {
                if (error?.name === 'AbortError') {
                    if (phase === 'connect') {
                        throw new Error(
                            `HTTP/2 connection to ${this.url} timed out after ${DEFAULT_CONNECT_TIMEOUT_SECONDS} seconds.`
                        )
                    }
                    throw new Error(
                        `HTTP/2 request to ${this.url} timed out after ${this.responseTimeoutInSeconds} seconds.`
                    )
                }
                throw error
            })
            .finally(() => {
                clearTimeout(connectTimeout)
            })

        phase = 'response'
        const responseTimeoutMs =
            this.responseTimeoutInSeconds === DEFAULT_RESPONSE_TIMEOUT_SECONDS
                ? DEFAULT_RESPONSE_TIMEOUT_MS
                : this.responseTimeoutInSeconds * 1000
        const responseTimeout =
            this.responseTimeoutInSeconds >= 0
                ? setTimeout(() => controller.abort(), responseTimeoutMs)
                : null

        const body = await response
            .arrayBuffer()
            .catch((error) => {
                if (error?.name === 'AbortError') {
                    throw new Error(
                        `HTTP/2 request to ${this.url} timed out after ${this.responseTimeoutInSeconds} seconds.`
                    )
                }
                throw error
            })
            .finally(() => {
                if (responseTimeout) {
                    clearTimeout(responseTimeout)
                }
            })

        const responseBytes = new Uint8Array(body)
        if (!response.ok) {
            throw new Error(
                `HTTP/2 request to ${this.url} failed with status ${response.status} ${response.statusText}. `
            )
        }
        return responseBytes
    }
}

/**
 * @param {unknown} error
 * @returns {boolean}
 */
function isTransientHttp2BrowserError(error) {
    if (!(error instanceof Error)) {
        return true
    }
    return !/^HTTP\/2 request to .* failed with status/.test(error.message)
}

/**
 * @param {unknown} error
 * @returns {string}
 */
function getErrorMessage(error) {
    return error instanceof Error ? error.message : String(error)
}

export { Http2ClientBrowser }
